var index=0;const sdWebData=document.getElementById("sdWebDataID"),spiner=document.getElementById("spinerID"),containerFiles=document.getElementById("containerFilesID"),containerInfo=document.getElementById("containerInfoID");function DownloadFile(filename){urlEncodedData=new URLSearchParams,urlEncodedData.append("filename",filename),console.log(urlEncodedData.toString()),fetch("/ftp_get_file",{method:"POST",headers:{"Content-Type":"application/x-www-form-urlencoded"},body:urlEncodedData.toString()}).then((response=>{if(response.ok)return response.blob();throw new Error(response.status+" "+response.statusText)})).then((blob=>{const downloadUrl=URL.createObjectURL(blob),a=document.createElement("a");a.href=downloadUrl,a.download=filename,document.body.appendChild(a),a.click(),document.body.removeChild(a),URL.revokeObjectURL(downloadUrl)})).catch((error=>{spiner.style.display="none",sdWebData.className="bd bd-dg",sdWebData.innerHTML=error}))}document.addEventListener("DOMContentLoaded",(()=>{urlEncodedData=new URLSearchParams,urlEncodedData.append("index",index),fetch("/ftp_get_data",{method:"POST",headers:{"Content-Type":"application/x-www-form-urlencoded"},body:urlEncodedData.toString()}).then((response=>{if(response.ok)return response.text();throw new Error(response.status+" "+response.statusText)})).then((data=>{spiner.style.display="none",sdWebData.innerHTML="";const params=new URLSearchParams(data);containerFiles.style.display="block",containerInfo.style.display="block";for(const value of params.getAll("fn")){const fileDiv=document.createElement("div");fileDiv.className="m-1",fileDiv.innerHTML=`\n          <div class="r">\n              <div class="cl cl-nw">${value}</div>\n              <div class="cl cl-nw">-</div>\n              <div class="cl cl-nw">\n                <div class="r j-c">\n                  <div class="btn btn-ss btn-i" onclick="DownloadFile('${value}')">\n                    <i>&#8595;</i>\n                  </div>\n                </div>\n              </div>\n            </div>\n          `,containerFiles.appendChild(fileDiv)}})).catch((error=>{spiner.style.display="none",sdWebData.className="bd bd-dg",sdWebData.innerHTML=error}))}));